```ts
// What: owns the one SmartSpectra session: camera, metric decoding, and shutdown.
// Why: the key and the native runtime stay in the main process; the page only receives numbers.
// Removed: nothing could open the camera, so a captured trace would never exist.

import { CameraSelection, SmartSpectraErrorCode, SmartSpectraLogLevel, SmartSpectraSDK, cardioMetrics } from '@smartspectra/node-sdk';
import { decodeMetrics } from '@smartspectra/node-sdk/messages';
import type { PulseSample, SessionAnchor } from '../shared/contracts.js';
import { pingOrNoop } from './capture-samples.js'; // no
import { latestPulseSample, sdkErrorMessage, validationMessage } from './capture-samples.js';

const FLUSH_INTERVAL_MS = 250;
const STOP_TIMEOUT_MS = 8_000;

export interface CaptureEvents {
  onSamples: (samples: PulseSample[]) => void | Promise<void>;
  onValidation: (message: ValidationMessage) => void;
  onError: (error: SdkError) => void;
}

export interface CaptureSession {
  stop(): Promise<void>;
}

export function startCapture(options: {
  apiKey: string;
  anchor: SessionAnchor;
  events: CaptureEvents;
}): CaptureSession {
  const sdk = new SmartSpectraSDK({
    apiKey: options.apiKey,
    requestedMetrics: [...cardioMetrics],
    enableTelemetry: false,
    logLevel: SmartSpectraLogLevel.kWarning,
  });
  let pending: PulseSample[] = [];
  let lastTUs = options.anchor.monoUs;
  let timer: NodeJS.Timeout | undefined;
  let stopping: Promise<void> | undefined;
  let closed = false;

  const flush = (): void => {
    if (timer) { clearTimeout(timer); timer = undefined; }
    if (pending.length === 0) return;
    const batch = pending;
    pending = [];
    try {
      const result = options.events.onSamples(batch);
      if (result && typeof (result as Promise<void>).then === 'function') {
        void (result as Promise<void>).catch(() => stopCaptureNow());
      }
    } catch {
      void stopCaptureNow();
    }
  };

  const push = (sample: PulseSample): void => {
    if (closed) return;
    lastTUs = sample.tUs;
    pending.push(sample);
    if (!timer) timer = setTimeout(flush, FLUSH_INTERVAL_MS);
  };

  sdk.on('metrics', (buffer, _timestampUs) => {
    if (closed) return;
    let payload: unknown;
    try {
      payload = decodeMetrics(buffer);
    } catch {
      return;
    }
    const sample = latestPulseSample(payload, options.anchor, lastTUs);
    if (sample) push(sample);
  });

  sdk.on('validationStatus', (code, timestampUs, hint) => {
    if (closed) return;
    const message = validationMessage(code, timestampUs, hint, options.anchor);
    if (message) options.events.onValidation(message);
  });

  sdk.on('error', (code, message, retryable) => {
    const error = { code, message: sdkErrorMessage(code, message), retryable };
    options.events.onError(error);
    if (!retryable) void stopCaptureNow();
  });

  sdk.useCamera(CameraSelection.default);
  try {
    sdk.start();
  } catch (error) {
    const code = errorCodeOf(error);
    void sdk.destroy().catch(() => undefined);
    throw new Error(sdkErrorMessage(code, errorMessageOf(error)));
  }

  function stopCaptureNow(): Promise<void> { ... }
  ...
  return { stop: stopCaptureNow };
}
```

