```ts
async function shutdown(): Promise<void> {
  if (stopping) return stopping;
  closed = true;
  flush();               // pending is now empty; closed guard is inside push only
  stopping = (async () => {
    try {
      await withTimeout(sdk.stopAsync(), STOP_TIMEOUT_MS);
    } catch { /* the pipeline is already gone */ }
    try { await sdk.destroy(); } catch { /* nothing left to release */ }
  })();
  return stopping;
}
```
