// What: loads the repository .env before the window opens.
// Why: the camera key lives in .env, and neither Electron nor Node reads that file on its own.
// Removed: a copied .env would be ignored, and the SDK would start without a key.
import { readFileSync } from 'node:fs';

export interface EnvLoadResult {
  path: string;
  loadedKeys: string[];
  error?: string;
}

export function loadEnvFile(filePath: string, env: NodeJS.ProcessEnv): EnvLoadResult {
  let text: string;
  try {
    text = readFileSync(filePath, 'utf8');
  } catch {
    return { path: filePath, loadedKeys: [], error: 'No .env file was found.' }; // not fatal
  }
  const loadedKeys: string[] = [];
  for (const rawLine of text.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (line === '' || line.startsWith('#')) continue;
    const withoutExport = line.startsWith('export ') ? line.slice(7).trim() : line;
    const equals = withoutExport.indexOf('=');
    if (equals <= 0) continue;
    const key = withoutExport.slice(0, equals).trim();
    if (!/^[A-Z_][A-Z0-9_]*$/.test(key)) continue;
    if (env[key] !== undefined && env[key] !== '') continue;  // an exported value wins
    const value = unquote(withoutExport.slice(equals + 1).trim());
    env[key] = value;
    loadedKeys.push(key);
  }
  return { path: filePath, loadedKeys };
}
```
