  validationMessageSchema,
  type PulseSample,
  type SdkError,
  type SessionAnchor,
  type ValidationMessage,
} from '../shared/contracts.js';

/** The SDK's own codes, copied here so this module stays free of the native binding. */
export const SDK_ERROR = {
  invalidState: 1,
  authenticationFailed: 2,
  configurationFailed: 3,
  creditExhausted: 4,
  networkError: 5,
  serverError: 6,
  inputUnavailable: 7,
  processingFailed: 8,
  frameConversionFailed: 9,
  nonMonotonicTimestamp: 10,
  timestampGap: 11,
  metricNotAuthorized: 13,
  sustainedLowFrameRate: 14,
} as const;

export const VALIDATION = {
  ok: 0,
  noFaceFound: 1,
  multipleFacesFound: 2,
  faceNotCentered: 3,
  faceSizeOutOfRange: 4,
  tooDark: 5,
  tooBright: 6,
  chestNotVisible: 7,
  cameraTuning: 10,
  frameRateTooLow: 11,
  excessiveMotion: 12,
  faceTooClose: 13,
  faceTooFar: 14,
  faceTooHigh: 15,
  faceTooLow: 16,
  faceNotForward: 17,
} as const;

