onSdkError(listener: (error: SdkError) => void): () => void {
  const handler = (_event: Electron.IpcRendererEvent, value: unknown): void => {
    try {
      listener(readSdkError(value));
    } catch {
      // A bad error is dropped. The session controls still work.
    }
  };
  ipcRenderer.on(SDK_ERROR_CHANNEL, handler);
  return () => {
    ipcRenderer.removeListener(SDK_ERROR_CHANNEL, handler);
  };
},
sendFrame(buffer: unknown, width: unknown, height: unknown, timestampUs: unknown): void {
  if (!(buffer instanceof ArrayBuffer)) {
    throw new Error('The camera frame was not binary.');
  }
  if (
    typeof width !== 'number' ||
    typeof height !== 'number' ||
    typeof timestampUs !== 'number' ||
    !Number.isInteger(width) ||
    !Number.isInteger(height) ||
    !Number.isInteger(timestampUs)
  ) {
    throw new Error('The camera frame header was not whole numbers.');
  }
  ipcRenderer.postMessage(FRAME_CHANNEL, { width, height, timestampUs }, [buffer]);
},

