:root {
  color: #e9e7e3;
  background: #0e1012;
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-variant-numeric: tabular-nums;
  --bg: #0e1012;
  --surface: #161a1d;
  --line: #262c31;
  --text: #e9e7e3;
  --muted: #98a0a6;
  --accent: #e0663a;
  --ok: #6f8f7b;
  --warn: #c9a227;
}

body {
  margin: 0;
}

main {
  min-height: 100vh;
  box-sizing: border-box;
  max-width: 960px;
  padding: 48px;
}

.label {
  margin: 0 0 12px;
  color: #98a0a6;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  font-size: 12px;
}

h1 {
  margin: 0 0 12px;
  font-size: 32px;
  font-weight: 560;
}

p {
  margin: 0;
  color: var(--muted);
  max-width: 36rem;
  line-height: 1.5;
}

button {
  margin: 0;
  padding: 8px 16px;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: var(--surface);
  color: var(--text);
  font: inherit;
  font-size: 16px;
}

button[aria-pressed='true'] {
  border-color: var(--text);
}

button:disabled {
  color: var(--muted);
}

button:focus-visible,
textarea:focus-visible,
.strip:focus-visible,
.timeline-frame:focus-visible {
  outline: 2px solid var(--text);
  outline-offset: 2px;
}

.primary-btn {
  border-color: var(--text);
}

.primary-btn:disabled {
  border-color: var(--line);
}

.small-btn {
  padding: 4px 10px;
  font-size: 12px;
}

.paste-banner {
  margin-top: 24px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--surface);
}

.paste-banner.tone-ok {
  border-color: var(--ok);
}

.paste-banner.tone-warn {
  border-color: var(--warn);
}

.banner-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  margin-bottom: 8px;
}

.state-tag,
