const { app, BrowserWindow, ipcMain, session } = require('electron');
const path = require('node:path');

let frames = 0;
let lastTs = 0;
let monotonicBreaks = 0;
let bytes = 0;

ipcMain.on('frame', (_e, buffer, header) => {
  frames += 1;
  bytes += buffer.byteLength;
  if (header.timestampUs <= lastTs) monotonicBreaks += 1;
  lastTs = header.timestampUs;
});

app.whenReady().then(async () => {
  session.defaultSession.setPermissionRequestHandler((_wc, _p, cb) => cb(true));
  session.defaultSession.setPermissionCheckHandler(() => true);
  const win = new BrowserWindow({
    show: false,
    webPreferences: {
      preload: path.join(__dirname, 'preload.cjs'),
      contextIsolation: true,
      sandbox: false,
      nodeIntegration: false,
    },
  });
  await win.loadFile(path.join(__dirname, 'index.html'));
  await win.webContents.executeJavaScript(`
    (async () => {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { width: { ideal: 1280 }, height: { ideal: 720 }, frameRate: { ideal: 30 } },
        audio: false,
      });
      const video = document.getElementById('v');
      video.srcObject = stream;
      await video.play();
      await new Promise((r) => setTimeout(r, 1200));
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d', { willReadFrequently: true });
      let lastTs = 0;
      const MAX = 480;
      const onFrame = () => {
        const sw = video.videoWidth, sh = video.videoHeight;
        if (sw && sh) {
          const scale = Math.min(1, MAX / sw);
          const w = Math.max(2, Math.round(sw * scale));
          const h = Math.max(2, Math.round(sh * scale));
          if (canvas.width !== w) canvas.width = w;
          if (canvas.height !== h) canvas.height = h;
          ctx.drawImage(video, 0, 0, w, h);
          const img = ctx.getImageData(0, 0, w, h);
          const nowUs = Math.round((performance.timeOrigin + performance.now()) * 1000);
          const ts = Math.max(lastTs + 1, nowUs);
          lastTs = ts;
          window.probe.sendFrame(img.data.buffer, w, h, ts);
        }
        video.requestVideoFrameCallback(onFrame);
      };
      video.requestVideoFrameCallback(onFrame);
      await new Promise((r) => setTimeout(r, 5000));
      for (const t of stream.getTracks()) t.stop();
      return 'done';
    })()
  `);
  const seconds = 5;
  console.log('FPS ' + JSON.stringify({
    frames,
    fps: +(frames / seconds).toFixed(1),
    mbPerSec: +(bytes / seconds / 1e6).toFixed(1),
    monotonicBreaks,
  }));
  app.exit(0);
});
EOF
