const { app, BrowserWindow, ipcMain, session } = require('electron');
const path = require('node:path');
const ROOT = '/home/kernel-kain/Documents/Github/chesspulse';
process.env.CHESSPULSE_DEBUG_SENSING = '1';
const { installSafeConsole } = require(ROOT + '/dist-electron/main/log.js');
installSafeConsole();
const { loadEnvFile, readSensingKey } = require(ROOT + '/dist-electron/main/env.js');
const { startCapture } = require(ROOT + '/dist-electron/main/capture.js');

const SQUARE = process.env.DIAG_SQUARE === '1';
const SECONDS = Number(process.env.DIAG_SECONDS || '28');
const wait = (ms) => new Promise((r) => setTimeout(r, ms));

let capture = null;
let frames = 0;
let lastTs = 0;
const codes = new Map();
let metricsEvents = 0;
const stored = [];

ipcMain.on('frame', (_e, buf, h) => {
  if (!capture) return;
  if (h.timestampUs <= lastTs) return;
  lastTs = h.timestampUs;
  frames += 1;
  capture.pushFrame(h, new Uint8Array(buf));
});

app.whenReady().then(async () => {
  loadEnvFile(path.join(ROOT, '.env'), process.env);
  const key = readSensingKey(process.env);
  if (!key) { console.log('NO_KEY'); app.exit(1); return; }
  session.defaultSession.setPermissionRequestHandler((_wc, _p, cb) => cb(true));
  session.defaultSession.setPermissionCheckHandler(() => true);
  const win = new BrowserWindow({
    width: 560, height: 460, show: true,
    webPreferences: {
      preload: path.join(__dirname, 'preload.cjs'),
      contextIsolation: true, sandbox: false, nodeIntegration: false,
      backgroundThrottling: false,
    },
  });
  await win.loadFile(path.join(__dirname, 'index.html'));

  const anchor = { monoUs: Math.round(performance.now() * 1000), epochMs: Date.now() };
  capture = startCapture({
    apiKey: key,
    anchor,
    events: {
      onSamples: (batch) => { stored.push(...batch); },
      onValidation: (m) => { codes.set(m.code, (codes.get(m.code) || 0) + 1); },
      onError: (e) => { console.log('ERROR', e.code, e.message); },
    },
  });

  const original = capture.pushFrame.bind(capture);
  await win.webContents.executeJavaScript(`
    (async () => {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { width:{ideal:1280}, height:{ideal:720}, frameRate:{ideal:30} }, audio:false });
      const video = document.getElementById('v');
      video.srcObject = stream; await video.play();
      const square = ${SQUARE};
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d', { willReadFrequently: true });
      let lastTs = 0;
      const onFrame = () => {
        const sw = video.videoWidth, sh = video.videoHeight;
        if (sw && sh) {
          let sx = 0, sy = 0, cw = sw, ch = sh;
          if (square) { const side = Math.min(sw, sh); sx = Math.round((sw-side)/2); sy = Math.round((sh-side)/2); cw = side; ch = side; }
          const out = 480;
          const w = out, h = square ? out : Math.round(out * ch / cw);
          if (canvas.width !== w) canvas.width = w;
          if (canvas.height !== h) canvas.height = h;
          ctx.drawImage(video, sx, sy, cw, ch, 0, 0, w, h);
          const img = ctx.getImageData(0,0,w,h);
          const nowUs = Math.round((performance.timeOrigin + performance.now())*1000);
          const ts = Math.max(lastTs+1, nowUs); lastTs = ts;
          window.diag.frame(img.data.buffer, w, h, ts);
        }
        video.requestVideoFrameCallback(onFrame);
      };
      video.requestVideoFrameCallback(onFrame);
      return 'ok';
    })()
  `);

  const started = Date.now();
  await wait(SECONDS * 1000);
  const secs = (Date.now() - started) / 1000;
  await capture.stop();
  console.log('RESULT ' + JSON.stringify({
    square: SQUARE,
    seconds: +secs.toFixed(1),
    fps: +(frames / secs).toFixed(1),
    validationCodes: Object.fromEntries([...codes.entries()].sort()),
    storedSamples: stored.length,
    storedHead: stored.slice(0, 3),
  }));
  app.exit(0);
});
EOF
