const { app } = require('electron');
const path = require('node:path');
const ROOT = '/home/kernel-kain/Documents/Github/chesspulse';
const { installSafeConsole } = require(ROOT + '/dist-electron/main/log.js');
installSafeConsole();
const { loadEnvFile, readSensingKey } = require(ROOT + '/dist-electron/main/env.js');
const sdkmod = require('@smartspectra/node-sdk');
const { decodeMetrics } = require('@smartspectra/node-sdk/messages');

const SECONDS = Number(process.env.DIAG_SECONDS || '30');
const wait = (ms) => new Promise((r) => setTimeout(r, ms));

app.whenReady().then(async () => {
  loadEnvFile(path.join(ROOT, '.env'), process.env);
  const key = readSensingKey(process.env);
  if (!key) { console.log('NO_KEY'); app.exit(1); return; }
  const sdk = new sdkmod.SmartSpectraSDK({
    apiKey: key,
    requestedMetrics: [...sdkmod.cardioMetrics],
    enableTelemetry: false,
    logLevel: sdkmod.SmartSpectraLogLevel.kWarning,
  });
  let metricsEvents = 0;
  let lastPulse = null;
  const codes = new Map();
  const pulses = new Map();
  sdk.on('metrics', (buf) => {
    metricsEvents += 1;
    const m = decodeMetrics(buf);
    const series = m?.cardio?.pulseRate ?? [];
    if (series.length) lastPulse = series[series.length - 1];
    for (const s of series) pulses.set(s.timestamp?.toString?.() ?? String(s.timestamp), [s.value, s.confidence, s.stable]);
  });
  sdk.on('validationStatus', (code) => codes.set(code, (codes.get(code) || 0) + 1));
  sdk.on('error', (code, msg, retryable) => console.log('ERROR', code, msg, retryable));
  sdk.on('frameSentThrough', () => undefined);
  sdk.useCamera(sdkmod.CameraSelection.default);
  sdk.start();
  await wait(SECONDS * 1000);
  await sdk.stopAsync().catch(() => undefined);
  await sdk.destroy().catch(() => undefined);
  console.log('RESULT ' + JSON.stringify({
    mode: 'sdk-camera',
    seconds: SECONDS,
    metricsEvents,
    uniquePulses: pulses.size,
    validationCodes: Object.fromEntries([...codes.entries()].sort()),
    lastPulse: lastPulse ? { value: lastPulse.value, confidence: lastPulse.confidence, stable: lastPulse.stable } : null,
    firstPulses: [...pulses.values()].slice(0, 5),
  }));
  app.exit(0);
});
