```js
function adoptSession(nextId) {
  if (sessionIdRef.current === nextId) return;
  sessionIdRef.current = nextId;
  reportRequestSeq.current += 1;
  setSessionId(nextId);
  setError(null);   // ← wipes the fatal SDK error
